def find_path(graph, start, goal):
    def dfs(node):
        if node == goal:
            return [goal]  # Return the path if we reach the goal
        path = None
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                path = dfs(neighbor)
                if path:
                    break
        if path:
            path = [node] + path  # Add the current node to the path
        return path

    visited = set()
    return dfs(start)

